package com.sobrenaturaldirector.composition.grammar;

import java.util.*;
import com.sobrenaturaldirector.composition.model.*;

public final class StructureGrammar {private StructureGrammar(){}public static StructureBlueprint build(String id,String theme,StructureScale scale,boolean boss,boolean reward){if(theme!=null&&theme.toLowerCase(Locale.ENGLISH).contains("catacomb"))return catacomb(id,theme,scale,boss,reward);List<StructureNode>n=new ArrayList<StructureNode>();List<StructureConnector>c=new ArrayList<StructureConnector>();List<String>path=new ArrayList<String>();add(n,c,path,"entrance",StructureNodeType.ENTRANCE,"entry",0,0,0);add(n,c,path,"approach",StructureNodeType.CORRIDOR,"approach",1,0,0);add(n,c,path,"main",StructureNodeType.ROOM,"main",2,0,0);if(boss)add(n,c,path,"arena",StructureNodeType.ARENA,"boss",3,0,0);if(reward)add(n,c,path,"reward",StructureNodeType.REWARD_ROOM,"reward",boss?4:3,0,0);add(n,c,path,"exit",StructureNodeType.EXIT,"exit",(boss?4:3)+(reward?1:0),0,0);return new StructureBlueprint(id,theme,scale,n,c,Collections.<StructureAnchor>emptyList(),path);}private static StructureBlueprint catacomb(String id,String theme,StructureScale scale,boolean boss,boolean reward){List<StructureNode>n=new ArrayList<StructureNode>();List<StructureConnector>c=new ArrayList<StructureConnector>();List<String>path=new ArrayList<String>();addAt(n,c,path,"cemetery",StructureNodeType.ROOM,"surface_cemetery",0,0,0);addAt(n,c,path,"entrance",StructureNodeType.ENTRANCE,"entrance",1,0,0);addAt(n,c,path,"descent",StructureNodeType.TRANSITION,"descent",1,-1,0);addAt(n,c,path,"inner_hall",StructureNodeType.CORRIDOR,"inner_hall",1,-2,0);addAt(n,c,path,"crypt_a",StructureNodeType.CRYPT,"crypt_a",2,-2,0);addAt(n,c,path,"crypt_b",StructureNodeType.CRYPT,"crypt_b",0,-2,0);c.add(new StructureConnector("link-inner-hall-crypt-b","inner_hall","crypt_b",StructureConnectorType.PASSAGE,true,"branch"));addAt(n,c,path,"antechamber",StructureNodeType.ROOM,"antechamber",1,-2,1);if(boss)addAt(n,c,path,"arena",StructureNodeType.ARENA,"boss",1,-2,2);if(reward)addAt(n,c,path,"reward",StructureNodeType.REWARD_ROOM,"reward",1,-2,3);addAt(n,c,path,"exit",StructureNodeType.EXIT,"exit",1,-2,(boss?3:2)+(reward?1:0));return new StructureBlueprint(id,theme,scale,n,c,Collections.<StructureAnchor>emptyList(),path);}private static void addAt(List<StructureNode>n,List<StructureConnector>c,List<String>p,String id,StructureNodeType t,String role,int x,int y,int z){String previous=n.isEmpty()?null:n.get(n.size()-1).getId();n.add(new StructureNode(id,t,role,"",true,new LogicalPosition(x,y,z),StructureStage.REVEAL,Collections.<String>emptyList()));p.add(id);if(previous!=null)c.add(new StructureConnector("link-"+previous+"-"+id,previous,id,StructureConnectorType.PASSAGE,true,"forward"));}private static void add(List<StructureNode>n,List<StructureConnector>c,List<String>p,String id,StructureNodeType t,String role,int x,int y,int z){addAt(n,c,p,id,t,role,x,y,z);}}
